import{_ as t,o as i,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph User + Dev Meeting 2022-05-04","description":"","frontmatter":{"title":"Ceph User + Dev Meeting 2022-05-04","date":"2022-05-04T00:00:00.000Z","updated":"2022-05-06T00:00:00.000Z","tags":["Ceph","NVM","Plugin System","Security","Storage Optimization"],"categories":["会议总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_User_+_Dev_Meeting_2022-05-04.md","filePath":"posts/2022/Ceph_User_+_Dev_Meeting_2022-05-04.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_User_+_Dev_Meeting_2022-05-04.md"};function p(n,e,o,_,a,g){return i(),l("div",null,[...e[0]||(e[0]=[s("<p>本次会议主要讨论了IBM的NVM设备在Ceph中的部署和插件系统的开发。以下是会议的关键点：</p><ol><li><p><strong>会议主题</strong>：介绍和讨论IBM的NVM设备在Ceph中的部署，以及相关插件系统的开发。</p></li><li><p><strong>参会人员</strong>：Martin Omar（IBM），会议主持人，及其他参与者。</p></li><li><p><strong>主要讨论内容</strong>：</p><ul><li>Martin介绍了IBM在NVM存储设备项目上的工作，这些设备具有在线压缩功能，逻辑块地址为22TB，但物理存储空间只有9.6TB。</li><li>讨论了如何通过插件系统支持IBM NVM设备，并创建了一个名为“xblock_device”的新插件系统。</li><li>新插件系统架构包括内核设备结构、插件注册和全局初始化。</li><li>讨论了使用Linux的capability system和&quot;keep caps&quot; flag来确保插件在权限切换时的安全性。</li></ul></li><li><p><strong>技术细节</strong>：</p><ul><li>创建了两个commit，一个包含插件系统和VDO设备的插件，另一个是针对FCM设备的插件和必要的Linux配置调整。</li><li>提出了对插件系统进行用户可配置的权限设置，以限制不必要的权限提升。</li></ul></li><li><p><strong>后续行动</strong>：</p><ul><li>Martin将继续测试FCM设备的插件，并希望未来能开放接口以便部署在其他客户环境中。</li><li>下一步是进行代码审查和添加更多的测试细节。</li></ul></li><li><p><strong>问题和反馈</strong>：</p><ul><li>讨论中提出对安全模型和插件系统的改进建议，如更精细化的权限控制和自动化测试。</li></ul></li><li><p><strong>会议结论</strong>：</p><ul><li>本次会议主要集中在IBM NVM设备的插件系统开发上，Martin提供了详细的技术介绍和演示，得到了积极的反馈。</li><li>确定了改进安全性和测试的计划，为未来的开发和部署奠定了基础。</li></ul></li></ol>",2)])])}const c=t(r,[["render",p]]);export{u as __pageData,c as default};
